    cache = dict()

    def wrapper(*args, **kwargs):
        key = id((args, kwargs)) if typed else id(args)
        if key in cache:
            result, timestamp = cache[key]
            if timestamp + ttl < timer():
                return result
            del cache[key]
        else:
