def deep_merge_nodes(nodes):
    res = []
    seen = {}
    for node in nodes:
        key, value = node
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            if key not in seen:
                seen[key] = None
                subres = deep_merge_nodes([(key, v) for k, v in value.nodes])
                res.append((key, subres))
            else:
                idx = res.index((key, None))
                subres = deep_merge_nodes([(key, v) for k, v in value.nodes])
                res[idx] = (key, subres)
        else:
            if key in seen:
                res[seen[key]] = (key, value)
                seen.pop(key)
            else:
                res.append(node)
                seen[key] = len(res) - 1
