import re
from decimal import Decimal

def size_to_bytes(size: str) -> int:
    size = size.strip().lower()
    match = re.search(r'\ in\s*(bytes|kb|m|g)', size)
    if not match:
        raise ValueError(f"Invalid file size format: {size}")

    unit = match.group().split()[1]
    magnitude = {
        'bytes': 1,
        'kb': 1024,
        'mb': 1024**2,
        'gb': 1024**3,
    }[unit]

    # Check if the scale is small enough to be an integer
    if magnitude < 1:
        return int(Decimal(size) * Decimal(magnitude))
    else:
        return int(Decimal(size) * Decimal(magnitude).quantize(Decimal('1'), rounding=Decimal.ROUND_HALF_UP))
