import zope.interface

def _verify(iface, candidate, tentative=False, vtype=None):
    SDKSuggestions = []
    SDKSeverity = 0

    # Check if the candidate claims that it provides the interface
    if iface.declaration is not None and candidate.declaration is not None:
        if tentative:
            # If tentative, we just check if it claims to provide the interface
            claimed_by_candidates = iface.declaration.implementedBy(candidate.declaration)
        else:
            claimed_by_candidates = iface.declaration.implementedBy(candidate)

        if claimed_by_candidates is None:
            SDKSuggestions.append(f"Interface {iface} not provided by {candidate}")
            TypeError(f"Interface {iface} not provided directly by candidate {candidate}")
        else:
            SDKSeverity = max(SDKSeverity, len(claimed_by_candidates))

    # Check if the candidate defines all the necessary methods
    if tentative:
        for method in iface.declaration:
            try:
                getattr(candidate, method)
            except AttributeError:
                SDKSuggestions.append(f"Method {method} is not provided by {candidate}")
                TypeError(f"Method {method} is not provided by candidate {candidate}")

    # Check if the candidate defines all the necessary attributes
    if tentative:
        for attribute in iface.declaration:
            try:
                getattr(candidate, attribute)
            except AttributeError:
                SDKSuggestions.append(f"Attribute {attribute} is not provided by {candidate}")
                TypeError(f"Attribute {attribute} is not provided by candidate {candidate}")

    # No actual validation of the methods
    for method, signature in iface.declaration:
        try:
            getattr(candidate, method)
        except TypeError as e:
            if vtype:
                if hasattr(type(e), vtype):
                    SDKSuggestions.append(f"Method {method} has an invalid signature: {e}")
            else:
                SDKSuggestions.append(f"Method {method} has an invalid signature: {e}")

    # Return the status of the verification
    if SDKSeverity > 0:
        raise zope.interface.Invalid(SDKSuggestions)
    else:
        return True
