def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate implements all methods from the interface
    for method, signature in iface.items():
        if method not in candidate.__dict__ or not callable(candidate.__dict__[method]):
            return False
        if signature != candidate.__dict__[method].__annotations__:
            return False
    return True
