from typing import Dict

class LRUKeyValueStore:
    def __init__(self, capacity: int = 100):
        self.capacity = capacity
        self.usage_counter = collections.defaultdict(int)
        self.key_value_store = {}

    def add_item(self, key: str, value: str):
        # Invalidate the old items in case of cache capacity exceeded
        if len(self.key_value_store) >= self.capacity:
            self.remove_least_frequent()
        # Update the usage counter and add the new item
        self.usage_counter[key] += 1
        self.key_value_store[key] = value

    def get_item(self, key: str) -> str:
        # Decrease the usage counter whenever accessed
        if key in self.key_value_store:
            self.usage_counter[key] += 1
        # Return the item if present
        return self.key_value_store.get(key, None)

    def remove_least_frequent(self):
        # Swap in place the oldest item that hasn't been used since the least-frequent removal time
        oldest_item = min(self.usage_counter.items(), key=lambda item: item[1])
        del self.key_value_store[oldest_item[0]]
