import os
import yaml
import json

class IRValidatorException(Exception):
    pass

class YAMLValidator:
    @classmethod
    def validate_from_file(cls, yaml_file=None):
        if yaml_file is None:
            yaml_file = os.path.join(os.getcwd(), 'default.yaml')

        if not os.path.isfile(yaml_file):
            raise FileNotFoundError(f"YAML file '{yaml_file}' not found")

        with open(yaml_file, 'r') as file:
            try:
                data = yaml.safe_load(file)
                cls.validate_data(data)
                return data
            except yaml.YAMLError as e:
                raise ValueError(f"Error loading YAML file: {e}")

    @classmethod
    def validate_data(cls, data):
        required_fields = ['field1', 'field2', 'field3']
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing mandatory field: {field}")
            if not isinstance(data[field], dict):
                raise IRValidatorException(f"Field '{field}' must be a dictionary")
            required_data_points = ['point1', 'point2', 'point3']
            for point in required_data_points:
                if point not in data[field]:
                    raise IRValidatorException(f"Missing mandatory point in field '{field}': {point}")
